"""Build a private, source-linked diagnosis from retained evidence only."""
import hashlib
import html
import json
import re
import xml.etree.ElementTree as ET
from datetime import datetime, timezone
from pathlib import Path

HERE = Path(__file__).parent
BASE = HERE.parent
cleanup = BASE / "obsolete-search-cleanup-20261102-01a19a01"
snapshot = json.loads((BASE / "z-drive-20261102" / "snapshot.json").read_text(encoding="utf-8-sig"))
summary = json.loads((cleanup / "summary.json").read_text(encoding="utf-8-sig"))
calls = json.loads((HERE / "saved-call-evidence.json").read_text(encoding="utf-8"))
inventory = json.loads((HERE / "wordpress-inventory.json").read_text(encoding="utf-8-sig"))
policy_receipt = json.loads((HERE / "policy-change-receipt.json").read_text(encoding="utf-8"))
filter_receipt = json.loads((HERE / "exclusion-install-receipt.json").read_text(encoding="utf-8"))
verification = json.loads((HERE / "filter-verification.json").read_text(encoding="utf-8"))

purposes = {
    27812: "SpaceSleuth name/context lookup while preparing a remote disk investigation",
    23076: "Light Will Win video-ID/title/schedule lookup in release, report and blog locations",
    42108: "Second, broader Light Will Win video-ID lookup across My Songs",
    19424: "FFmpeg/ffprobe CI configuration lookup across repositories and Tools",
    24936: "RastaMoves spelling/tool lookup before resolving RasterMoves",
    24848: "Polyphony document-title lookup during the schedule chat's follow-up work",
    16004: "Analytics and platform-monitoring runbook lookup",
    30136: "Platform-monitoring coverage lookup for a recommendation",
}
stops = {}
for filename in ("stopped-searches.json", "superseded-active-chat-searches.json", "final-search-stops.json"):
    for receipt in json.loads((cleanup / filename).read_text(encoding="utf-8-sig")):
        if receipt.get("Outcome") in ("stopped", "stop_requested"):
            stops[receipt["Pid"]] = receipt.get("CheckedAt", receipt.get("At"))
processes = {p["ProcessId"]: p for p in snapshot["SearchProcesses"]}
triggers = []
for call in calls:
    pid = call["pid"]
    process = processes[pid]
    launch = call["launches"][0]
    stop = stops.get(pid)
    age = None
    if stop:
        age = round((datetime.fromisoformat(stop.replace("Z", "+00:00")) - datetime.fromisoformat(process["CreationDate"])).total_seconds() / 60, 1)
    triggers.append({"pid": pid, "purpose": purposes[pid], "started": process["CreationDate"], "stop_requested_at": stop, "approximate_elapsed_minutes": age, "outcome": "stopped_and_exit_verified_by_cleanup" if stop else "finished_independently_before_cleanup", "command": process["CommandLine"], "owning_session": call["file"], "launch_line": launch["line"], "launch_call_id": launch["call_id"], "prints_only_output": "text(r.output)" in launch["input"], "outer_cell_explicitly_terminated": pid == 27812})

pattern = re.compile(r"ripgrep|orphan(?:ed)? (?:process|search|scan)|build.cache|disk contention|drive.scan|background.terminals", re.I)
duplicate_hits = []
statuses = {}
for post in inventory["posts"]:
    status = post.get("status", "unknown")
    statuses[status] = statuses.get(status, 0) + 1
    text = " ".join(str(post.get(k, {}).get(v, "")) for k in ("title", "content") for v in ("raw", "rendered"))
    if pattern.search(text):
        duplicate_hits.append({"id": post["id"], "status": status, "url": post["link"]})
assessment = {"task": "Identify the triggers and lifetime failure behind eight orphaned Z: searches; prevent wasteful generated-storage discovery", "decision": "PASS", "reason": "A verified technical failure diagnosis explains how broad context searches and lost child-process ownership caused hours of unnecessary storage activity; the cause can be explained without private filenames or task payloads.", "angle": "How an apparently completed agent tool call left its disk search running, and how source-scoped discovery avoids crawling build and cache trees", "evidence": ["../z-drive-20261102/snapshot.json", "../obsolete-search-cleanup-20261102-01a19a01/summary.json", "saved-call-evidence.json", "filter-verification.json", "policy-change-receipt.json", "exclusion-install-receipt.json"], "duplicate_check": {"source": "Fresh authenticated WordPress inventory of published, future, draft, pending and private posts", "statuses": statuses, "searched_fields": ["title", "content"], "terms": pattern.pattern, "matching_posts": duplicate_hits, "result": "No matching existing article or pending draft found" if not duplicate_hits else "Related material requires editorial review"}, "state": "blocked", "blocker": "An article still needs a sanitised demonstration of command yield versus actual process lifetime and fresh pictorial featured artwork; private machine/session logs must not be published verbatim.", "next_action": "Named continuation: Orphan-search diagnosis article. Prepare a short safe demonstration and article-specific artwork using project-blog-writer, then draft the public-safe explanation. No publication action was performed in this diagnostic task."}

report = {"owner_chat": "01a19a0f-2359-7830-8a2f-263f78c8a55a", "completed_at": datetime.now(timezone.utc).isoformat(), "conclusion": "Eight Codex-launched ripgrep context-discovery searches across six chats were scoped too broadly. Six completed orchestration cells printed only r.output, hiding command status/session metadata; another outer cell was explicitly terminated without stopping its native search. The owning chats moved on while searches remained alive.", "triggers": triggers, "verified_contributing_factors": ["Two content searches covered all of My Songs; others covered large Reports, Tools or multi-repository trees.", "Blanket --hidden and inadequate generated-storage exclusions expanded discovery; actual output from the video-ID lookup contains .pnpm-store and many .tmp build/test paths.", "The FFmpeg lookup searched every repository/worktree instead of the current owning checkout.", "yield_time_ms and output caps limited waiting/display, not native search lifetime.", "No search-exit verification was retained by the owners before moving on; the later cleanup checked native identities and verified all eight gone."], "lifecycle_example": {"pid": 27812, "search_launch": "2026-11-01T23:31:16.342Z", "outer_cell": "g8:73", "outer_termination_request": "2026-11-01T23:31:29.192Z", "native_search_stop_request": stops[27812], "observation": "The native rg process and pwsh wrapper survived the outer-cell termination and were found in the later process inventory."}, "uncertainty": ["No exact per-file I/O trace was available; Windows denied the earlier tracing attempt. Generated-tree traversal is directly evidenced, but its share of bytes/time is unknown.", "This diagnoses agent command/lifecycle handling; it does not establish a specific app-server implementation bug or prove that a runtime defect was repaired.", "The original commands searched My Songs, not necessarily every directory on the entire Z: volume.", "No new storage-load measurements or sustained-performance-recovery claim were made.", "Saving instructions does not prove receipt/adoption by every already-running chat."], "changes": {"instructions": policy_receipt, "default_rg_filters": filter_receipt, "verification": verification, "hard_limits": "rgignore affects ordinary ripgrep discovery; direct paths, explicit overrides and other recursion tools require the shared scope/lifecycle rule. It is not a universal runtime block."}, "danceflow": "Shared ecosystem guidance and discovery were consulted. The useful improvement is shared discovery policy plus ripgrep's native ignore primitive; no additional engine, model run or software release is justified.", "media": {"included": "Generated evidence-linked lifecycle diagram, search-lifecycle.svg", "omitted": "No retrospective screenshot/video can prove the killed processes were alive. No live interface changed, and a new failure demonstration would be separate bounded work. The diagram is explicitly labelled as an illustration from retained evidence."}, "blogworthiness": assessment}
(HERE / "cause-report.json").write_text(json.dumps(report, indent=2), encoding="utf-8")
(HERE / "blogworthiness.json").write_text(json.dumps(assessment, indent=2), encoding="utf-8")

svg = '''<svg xmlns="http://www.w3.org/2000/svg" width="1100" height="300" viewBox="0 0 1100 300" role="img" aria-labelledby="title desc"><title id="title">Search lifetime and missed cleanup</title><desc id="desc">A narrow context question led to a broad search, the outer cell finished or stopped, and the native search continued until explicit cleanup.</desc><rect width="1100" height="300" fill="#f6f8fc"/><g font-family="Arial,sans-serif" fill="#15233b"><text x="36" y="38" font-size="22" font-weight="bold">One question, two different lifetimes</text><g fill="#e1ebff" stroke="#8da9d7"><rect x="36" y="72" width="220" height="92" rx="12"/><rect x="300" y="72" width="220" height="92" rx="12"/><rect x="564" y="72" width="220" height="92" rx="12"/><rect x="828" y="72" width="236" height="92" rx="12"/></g><g font-size="17"><text x="56" y="105">Find one ID / setting</text><text x="56" y="134">or existing document</text><text x="320" y="105">Broad recursive rg</text><text x="320" y="134">includes generated trees</text><text x="584" y="105">Outer cell ends</text><text x="584" y="134">child exit unverified</text><text x="848" y="105">Native rg stays alive</text><text x="848" y="134">until explicit cleanup</text></g><g stroke="#6b7c99" stroke-width="3"><path d="M260 118h32m232 0h32m232 0h32"/></g><text x="36" y="211" font-size="17">Verified example: outer cell stopped at 23:31:29; native search stopped at 02:17:58.</text><text x="36" y="241" font-size="15">Prevention: named source scope + generated-storage exclusions + retain session metadata + verify child exit.</text><text x="36" y="276" font-size="13" fill="#5a6780">Generated illustration from retained 1–2 November 2026 logs and process receipts; not a new execution capture.</text></g></svg>'''
ET.fromstring(svg)
(HERE / "search-lifecycle.svg").write_text(svg, encoding="utf-8")
rows = "".join(f"<tr><td>{x['pid']}</td><td>{html.escape(x['purpose'])}</td><td>{html.escape(x['started'][:19].replace('T', ' '))}</td><td>{str(x['approximate_elapsed_minutes']) + ' min' if x['approximate_elapsed_minutes'] else 'Finished independently'}</td></tr>" for x in triggers)
body = f'''<!doctype html><html lang="en"><meta charset="utf-8"><title>Cause of orphaned Z: searches</title><style>body{{font:17px/1.55 system-ui,sans-serif;max-width:1120px;margin:40px auto;padding:0 24px;color:#18263c}}h1{{line-height:1.2}}img{{width:100%;height:auto}}table{{border-collapse:collapse;width:100%;font-size:14px}}td,th{{border-bottom:1px solid #ccd4df;padding:10px;text-align:left;vertical-align:top}}code{{background:#f0f3f7;padding:2px 5px}}.note{{color:#50627b}}a{{color:#174aa1}}</style><h1>Cause of the orphaned Z: searches</h1><p>{html.escape(report['conclusion'])}</p><img src="search-lifecycle.svg" alt="Illustrated chain from a narrow context question to an unmanaged native search"><p class="note">Generated illustration from saved evidence, not a new process capture. Times are Europe/London (GMT).</p><h2>What triggered them</h2><table><thead><tr><th>PID</th><th>Context lookup</th><th>Native start</th><th>Approximate lifetime</th></tr></thead><tbody>{rows}</tbody></table><h2>Why they ran for so long</h2><p>These were ad-hoc agent context lookups. Searches widened beyond the owning files or repository, descended into storage irrelevant to the question, and were not reaped when the chat moved on. Saved video-ID output explicitly names <code>.pnpm-store</code> and numerous <code>.tmp</code> trees. Several wrappers emitted only <code>r.output</code>, suppressing the metadata needed to manage a yielded command.</p><p>The strongest example is PID 27812: the outer <code>functions.exec</code> cell was stopped at 23:31:29, but its native search remained alive until the later cleanup at 02:17:58. This is evidence of missed child cleanup, not proof of a particular app implementation defect.</p><h2>Prevention applied</h2><p>The shared Codex instructions and My Songs opening guide now require named source scope, generated-storage exclusions and complete search lifecycle ownership. Default <code>.rgignore</code> files were installed in My Songs and Syn. A tiny local fixture verified source/document retention, exclusion of generated trees, and the behaviour of explicit globs. No new Z: discovery scan was run.</p><p class="note">These are default search filters and instructions. Direct paths, explicit ignore overrides and PowerShell recursion can bypass ripgrep filters; running-chat adoption and a universal runtime block are not claimed.</p><h2>Evidence and limitations</h2><p><a href="cause-report.json">Structured cause report</a> · <a href="saved-call-evidence.json">Exact owning launch records</a> · <a href="../z-drive-20261102/snapshot.json">Original process snapshot</a> · <a href="../obsolete-search-cleanup-20261102-01a19a01/summary.json">Verified cleanup receipt</a> · <a href="filter-verification.json">Local filter verification</a> · <a href="policy-change-receipt.json">Instruction readback</a></p><p>Windows denied the earlier detailed I/O trace, so the exact per-file and per-process share of contention remains unknown. The earlier cleanup verified seven searches stopped and the eighth finished independently. This task makes no sustained disk-recovery claim. Screenshots or video cannot retroactively establish the killed processes' prior state; the retained native records provide that evidence.</p><h2>Blogworthiness: PASS</h2><p>{html.escape(assessment['reason'])}</p><p>The current authenticated inventory contains 39 published posts, three drafts and one future post. No matching article was found in titles or bodies for the recorded duplicate-check terms. <strong>Delivery blocked:</strong> {html.escape(assessment['blocker'])}</p><p>{html.escape(assessment['next_action'])}</p></html>'''
(HERE / "cause-report.html").write_text(body, encoding="utf-8")
for href in re.findall(r'(?:href|src)="([^"]+)"', body):
    assert (HERE / href).exists(), href
assert all(hashlib.sha256(Path(x["path"]).read_bytes()).hexdigest() == x["sha256"] for x in filter_receipt["files"])
print(json.dumps({"report": str(HERE / "cause-report.html"), "native_searches": len(triggers), "launches_mapped": len(calls), "blog_duplicate_hits": duplicate_hits, "filter_readbacks_match": True, "diagram_valid_xml": True, "local_links_exist": True}))
